 const vertex=`uniform float uScrollSpeed;uniform float uCurveStrength;uniform float uCurveFrequency;varying vec2 vUv;void main(){vec3 pos=position;vec3 worldPosition=(modelMatrix*vec4(position,1.)).xyz;float d=uCurveStrength*cos(worldPosition.y*uCurveFrequency);pos.x+=d-uCurveStrength;pos.y-=sin(uv.x*3.141592653)*uScrollSpeed;gl_Position=projectionMatrix*modelViewMatrix*vec4(pos,1.);vUv=uv;}`;
