 const group=new THREE.Group();scene.add(group);const meshes=[],geo=new THREE.PlaneGeometry(1,1,20,20),height=1.55,width=1.75,gap=.16,total=photos.length*(height+gap);
 for(let col=0;col<3;col++)for(let i=0;i<photos.length;i++){const tex=textures[(i+col*3)%photos.length];const material=new THREE.ShaderMaterial({vertexShader:vertex,fragmentShader:fragment,uniforms:{uTexture:{value:tex},uScrollSpeed:{value:0},uCurveStrength:{value:.55},uCurveFrequency:{value:.52},uImageSize:{value:new THREE.Vector2(tex.image.width,tex.image.height)},uPlaneSize:{value:new THREE.Vector2(width,height)}}});const mesh=new THREE.Mesh(geo,material);mesh.scale.set(width,height,1);mesh.userData={photo:(i+col*3)%photos.length,col,i};mesh.position.x=(col-1)*(width+.16)+.15;group.add(mesh);meshes.push(mesh)}
 let lastSelected=-1,visible=false,paused=false,drag=false,offset=0,velocity=0,last=performance.now(),pointerY=0,downY=0,downX=0,moved=false;let pointerSpeed=0,targetX=0,targetY=0,currentX=0,currentY=0,previousX=0,previousY=0;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function resize(){const r=canvas.parentElement.getBoundingClientRect();if(r.width<1)return;renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.position.z=r.width<700?8.8:5.4;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(canvas.parentElement);resize();
 const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();
 canvas.addEventListener('pointerdown',e=>{drag=true;pointerY=e.clientY;downY=e.clientY;downX=e.clientX;moved=false;onDrag(false);canvas.setPointerCapture(e.pointerId)});
 canvas.addEventListener('pointermove',e=>{if(!drag)return;const d=(e.clientY-pointerY)*.008;offset+=d;velocity=d*2;pointerY=e.clientY;if(Math.hypot(e.clientY-downY,e.clientX-downX)>8){moved=true;onDrag(true)}});
 canvas.addEventListener('pointerup',e=>{drag=false;if(!moved){const r=canvas.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects(meshes)[0];if(hit)onSelect(hit.object.userData.photo)}if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);setTimeout(()=>onDrag(false),120)});canvas.addEventListener('pointercancel',()=>{drag=false;onDrag(false)});
 document.addEventListener('pointermove',e=>{if(!visible||paused||reduce||e.pointerType!=='mouse')return;targetX=(e.clientX/innerWidth-.5)*.12;targetY=(e.clientY/innerHeight-.5)*.1;pointerSpeed=Math.min(.12,Math.hypot(e.clientX-previousX,e.clientY-previousY)*.0005);previousX=e.clientX;previousY=e.clientY},{passive:true});
 canvas.tabIndex=0;canvas.addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();offset+=(e.key==='ArrowDown'?1:-1)*.8;velocity=.08}});
 function render(now){const dt=Math.min(.05,(now-last)/1000);last=now;requestAnimationFrame(render);if(!visible||document.hidden)return;if(!paused&&!drag&&!document.querySelector('dialog[open]')){offset+=dt*(.36+pointerSpeed);currentX+=(targetX-currentX)*.055;currentY+=(targetY-currentY)*.055;group.rotation.y=currentX;group.rotation.x=currentY;velocity*=.91;pointerSpeed*=.94;}else if(paused){velocity=0;}meshes.forEach(mesh=>{const {col,i}=mesh.userData;const direction=col===1?1:-1;const speed=[.8,1,.65][col];let y=i*(height+gap)+offset*direction*speed+col*.45;y=((y+total/2)%total+total)%total-total/2;mesh.position.y=y;mesh.material.uniforms.uScrollSpeed.value=reduce?0:Math.max(-.25,Math.min(.25,velocity*direction));});if(!paused||lastSelected===-1){const center=meshes.filter(m=>m.userData.col===1).reduce((a,b)=>Math.abs(a.position.y)<Math.abs(b.position.y)?a:b);if(lastSelected!==center.userData.photo){lastSelected=center.userData.photo;onSelect(lastSelected)}}renderer.render(scene,camera)}requestAnimationFrame(render);
 return {setVisible(v){visible=v;resize()},setPaused(v){paused=v},step(dir){lastSelected=-1;offset+=dir*1.2;velocity=dir*.15}};
